    start = date.fromisoformat(start_date)
    end = date.fromisoformat(end_date)
    if start > end:
        return 0
    total_days = (end - start).days + 1
    # Count Saturdays (weekday 5) and Sundays (weekday 6)
    # A full week has 2 weekend days; the remainder days from start's weekday determine the rest
    full_weeks, remainder = divmod(total_days, 7)
    weekend_count = full_weeks * 2
    # Count weekend days in the partial week starting at `start`
    for i in range(remainder):
        if (start.weekday() + i) % 7 in (5, 6):
            weekend_count += 1
    return total_days - weekend_count

