def count_business_days(start_date: str, end_date: str) -> int:
    # Parse the ISO strings – only allow a pure date (YYYY-MM-DD). Anything with
    # a time component or timezone information raises an error.
    try:
        start = datetime.date.fromisoformat(start_date)
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}")
    try:
        end = datetime.date.fromisoformat(end_date)
    except ValueError:
        raise ValueError(f"Invalid end date: {end_date!r}")

    # If the start date is after the end date, return 0.
    if start > end:
        return 0

    # Helper: count business days from day 0 up to and including `d`.
    def _business_up_to(d: datetime.date) -> int:
        # Total days from the epoch (1 Jan 1) to `d` inclusive.
        total_days = (d - datetime.date(1, 1, 1)).days + 1
        # Number of complete weeks and the remainder weekday.
        full_weeks, remainder = divmod(total_days, 7)
        # Each full week contains exactly 5 business days (Mon–Fri).
        business = full_weeks * 5
        # Add business days from the partial week.
        # weekday(): Monday==0, Sunday==6
        for i in range(remainder):
            if i < 5:          # the first five weekdays are business days
                business += 1
        return business

    # Business days up to `end` minus business days up to the day before `start`.
    # Using `start - datetime.timedelta(days=1)` works even when start == 1 Jan 1
    # (the subtraction yields a date before the epoch, which is fine for the helper).
    return _business_up_to(end) - _business_up_to(start - datetime.timedelta(days=1))

